from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v22r2
from taf.selenium.sbts.pages import v23r2
from taf.selenium.sbts.common.exceptions import ParamValueError


class Diagnostic(v23r2.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._debug_tracing = DebugTracingPage(driver)
        self._test_setup = TestSetupPage(driver)


class DebugTracingPage(v23r2.diagnostic.DebugTracingPage):
    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)

    def configure_iq_capture(
            self,
            enable_capture_on_event,
            capture_event=False,
            ul_subcell_index_list=None,
            dl_subcell_index_list=None,
            lte_ul_cell_ids=None,
            lte_dl_cell_ids=None,
            buffer_cycle=None,
            capture_frame_offset=None,
            radio_configurations=None
    ):
        self._detail_panel.close_details_panel()
        return self._view_panel.configure_iq_capture(enable_capture_on_event=enable_capture_on_event,
                                                     capture_event=capture_event,
                                                     ul_subcell_index_list=ul_subcell_index_list,
                                                     dl_subcell_index_list=dl_subcell_index_list,
                                                     lte_ul_cell_ids=lte_ul_cell_ids,
                                                     lte_dl_cell_ids=lte_dl_cell_ids,
                                                     buffer_cycle=buffer_cycle,
                                                     capture_frame_offset=capture_frame_offset,
                                                     radio_configurations=radio_configurations)

    def disable_iq_capture(self, timeout=60):
        self._detail_panel.close_details_panel()
        return self._view_panel.disable_iq_capture(timeout)

    def start_parallel_l1_l2_mirroring(self, timeout=60):
        self._detail_panel.close_details_panel()
        return self._view_panel.start_parallel_l1_l2_mirroring(timeout)


class DebugTracingPageViewPanel(v23r2.diagnostic.DebugTracingPageViewPanel):
    _START_PARALLEL_L1_L2_MIRRORING = ('//section[@class="uPlane-component"]//ui-button[contains(translate(@a-text, '
                                       '"ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz"), "start parallel")]'
                                       '//button')
    _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH = '//section[@class="uPlane-component"]//div[contains(text(), "{}")]'
    _CAPTURE_ON_EVENT_FROM_BBU_RU_INPUT = _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH + '/following-sibling::div//input'
    _CAPTURE_ON_EVENT_FROM_BBU_RU_CHECKBOX = _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH + '/following-sibling::div//span'
    _BUFFER_CYCLE_DROPDOWN_BUTTON = _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH + '/following-sibling::div//button'
    _BUFFER_CYCLE_OPTION = _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH + '/following-sibling::div//li'
    _CAPTURE_FRAME_OFFSET = _L1_IQ_CAPTURE_SUBCELL_LABEL_XPATH + '/following-sibling::div//input'
    _RMOD_CONFIGURATIONS_XPATH = ('//*[contains(text(), "{}")]/ancestor::div[1]//following-sibling::div'
                                  '//div[*[contains(text(), "{}")]]/following-sibling::div')
    _CONFIGURE_IQ_CAPTURE_STATUS = ('//section[@class="uPlane-component"]'
                                    '//*[contains(@class, "operation-status")]/wf-inlineinfo')
    _CONFIGURING_STATUS = _CONFIGURE_IQ_CAPTURE_STATUS + '[contains(@title, "Configuring...")]'
    _DISABLE_IQ_CAPTURE_BUTTON_XPATH = ('//section[@class="uPlane-component"]//ui-button[contains(translate(@a-text, '
                                        '"ABCDEFGHIJKLMNOPQRSTUVWXYZ", "abcdefghijklmnopqrstuvwxyz"), '
                                        '"disable iq capture")]//button')
    _DISABLING_STATUS = _CONFIGURE_IQ_CAPTURE_STATUS + '[contains(@title, "Disabling..")]'
    _START_PARALLEL_STATUS = _CONFIGURE_IQ_CAPTURE_STATUS + '[contains(@title, "mirroring..")]'
    _MINUS_FORTY_FIVE_POLARIZATION = '-45 Polarization'
    _PLUS_FORTY_FIVE_POLARIZATION = '+45 Polarization'

    def __init__(self, driver):
        super(DebugTracingPageViewPanel, self).__init__(driver)

    def configure_iq_capture(
            self,
            enable_capture_on_event,
            capture_event=False,
            ul_subcell_index_list=None,
            dl_subcell_index_list=None,
            lte_ul_cell_ids=None,
            lte_dl_cell_ids=None,
            buffer_cycle=None,
            capture_frame_offset=None,
            radio_configurations=None
    ):
        elem = self.driver.find_element_by_xpath(self._L1_IQ_CAPTURE_XPATH)
        self._scroll_elem_into_view(elem, "start", "nearest")
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_operation(self._COMPONENT_TYPE, self._CONFIGURE)
        self.select_checkbox_by_specified_status(enable_capture_on_event,
                                                 self._CAPTURE_EVENT_INPUT_XPATH,
                                                 self._CAPTURE_EVENT_CHECKOUT_XPATH)

        self._configure_with_capture_on_event(capture_event,
                                              ul_subcell_index_list,
                                              dl_subcell_index_list,
                                              buffer_cycle,
                                              capture_frame_offset,
                                              radio_configurations)
        self._input_cell_ids(self._LTE_UL_CELL_IDS, lte_ul_cell_ids)
        self._input_cell_ids(self._LTE_DL_CELL_IDS, lte_dl_cell_ids)
        self.click_enabled_element((By.XPATH, self._APPLY_CONFIGURATION_BUTTON_XPATH))
        self.wait_for_visibility_by_xpath(self._CONFIGURING_STATUS)
        self.wait_for_invisibility((By.XPATH, self._CONFIGURING_STATUS))
        return self.get_attribute_by_xpath(self._CONFIGURE_IQ_CAPTURE_STATUS, "title")

    def _configure_with_capture_on_event(self,
                                         capture_event,
                                         ul_subcell_index_list,
                                         dl_subcell_index_list,
                                         buffer_cycle,
                                         capture_frame_offset,
                                         radio_configurations):
        if not capture_event:
            self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)
            self._select_subcell_list(self._DL_SUBCELL, dl_subcell_index_list)
            return

        on_event_xpath = self._CAPTURE_ON_EVENT_FROM_BBU_RU_CHECKBOX.format("Capture on event")
        elem = self.driver.find_element_by_xpath(on_event_xpath)
        self._scroll_elem_into_view(elem)
        self.select_checkbox_by_specified_status(capture_event,
                                                 self._CAPTURE_ON_EVENT_FROM_BBU_RU_INPUT.format("Capture on event"),
                                                 on_event_xpath)
        self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)

        if not buffer_cycle:
            raise ParamValueError('buffer_cycle can not be None with capture_event True')
        if not capture_frame_offset:
            raise ParamValueError('capture_frame_offset can not be None with capture_event True')
        if not radio_configurations:
            raise ParamValueError('radio_configurations can not be None with capture_event True')
        self._select_buffer_cycle(buffer_cycle)
        self._input_capture_frame_offset(capture_frame_offset)
        self._configure_multiple_radios(radio_configurations)

    def _select_buffer_cycle(self, buffer_cycle):
        buffer_cycle_xpath = self._BUFFER_CYCLE_OPTION.format('Buffer cycle')
        elem = self.driver.find_element_by_xpath(buffer_cycle_xpath)
        self._scroll_elem_into_view(elem)
        self.select_element_from_dropdown_list_by_text_and_click(
            buffer_cycle,
            (By.XPATH, self._BUFFER_CYCLE_DROPDOWN_BUTTON.format('Buffer cycle')),
            (By.XPATH, buffer_cycle_xpath),
        )

    def _input_capture_frame_offset(self, capture_frame_offset):
        capture_frame_offset_xpath = self._CAPTURE_FRAME_OFFSET.format("Capture frame offset")
        elem = self.driver.find_element_by_xpath(capture_frame_offset_xpath)
        self._scroll_elem_into_view(elem)
        self.insert_text_to_enable_element((By.XPATH, capture_frame_offset_xpath),
                                           capture_frame_offset)

    def _configure_multiple_radios(self, radio_configurations):
        for rmod, configurations in radio_configurations.items():
            self._configure_radio(rmod, configurations)

    def _configure_radio(self, rmod, configurations):
        elem = self.driver.find_element_by_xpath(self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list'))
        self._scroll_elem_into_view(elem)
        self.select_element_from_dropdown_list_by_text_and_click(
            configurations['Antenna list'],
            (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list') + "//button"),
            (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, 'Antenna list') + "//ul//span")
        )
        self._configure_polarization(rmod,
                                     self._PLUS_FORTY_FIVE_POLARIZATION,
                                     configurations.get(self._PLUS_FORTY_FIVE_POLARIZATION, None))
        self._configure_polarization(rmod,
                                     self._MINUS_FORTY_FIVE_POLARIZATION,
                                     configurations.get(self._MINUS_FORTY_FIVE_POLARIZATION, None))
        self.insert_text_to_enable_element(
            (By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, "Capture activity timer") + "//input"),
            configurations['capture_activity_timer']
        )

    def _configure_polarization(self, rmod, polarization_name, polarizations):
        if not polarizations:
            return

        polarization_button = self._RMOD_CONFIGURATIONS_XPATH.format(rmod, polarization_name) + "//button"
        elem = self.driver.find_element_by_xpath(polarization_button)
        self._scroll_elem_into_view(elem)

        span_elements = self.expand_dropdown_list_and_return_elements(
            button_locator=(By.XPATH, polarization_button),
            option_locator=(By.XPATH, self._RMOD_CONFIGURATIONS_XPATH.format(rmod, polarization_name) + "//label//span")
        )
        checkbox_elems = self.driver.find_elements_by_xpath(
            self._RMOD_CONFIGURATIONS_XPATH.format(rmod, polarization_name) + "//ul//input"
        )
        polarizations = [str(item) for item in polarizations]
        for span, checkbox in zip(span_elements, checkbox_elems):
            if span.text in polarizations and not checkbox.is_selected():
                span.click()
            if span.text not in polarizations and checkbox.is_selected():
                span.click()
        self.click_enabled_element((By.XPATH,
                                    self._RMOD_CONFIGURATIONS_XPATH.format(rmod, polarization_name) + "//button"))

    def disable_iq_capture(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        elem = self.driver.find_element_by_xpath(self._DISABLE_IQ_CAPTURE_BUTTON_XPATH)
        self._scroll_elem_into_view(elem, "start", "nearest")
        self.click_enabled_element((By.XPATH, self._DISABLE_IQ_CAPTURE_BUTTON_XPATH), timeout)
        self.wait_for_visibility_by_xpath(self._DISABLING_STATUS)
        self.wait_for_invisibility((By.XPATH, self._DISABLING_STATUS))
        return self.get_attribute_by_xpath(self._CONFIGURE_IQ_CAPTURE_STATUS, "title")

    def start_parallel_l1_l2_mirroring(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        elem = self.driver.find_element_by_xpath(self._START_PARALLEL_L1_L2_MIRRORING)
        self._scroll_elem_into_view(elem)
        self.click_enabled_element((By.XPATH, self._START_PARALLEL_L1_L2_MIRRORING), timeout)
        self.wait_for_visibility_by_xpath(self._START_PARALLEL_STATUS)
        self.wait_for_invisibility((By.XPATH, self._START_PARALLEL_STATUS))
        return self.get_attribute_by_xpath(self._CONFIGURE_IQ_CAPTURE_STATUS, "title")


class TestSetupPage(v22r2.diagnostic.TestSetupPage):
    def __init__(self, driver):
        super(TestSetupPage, self).__init__(driver)
        self._view_panel = TestSetupPageViewPanel(driver)


class TestSetupPageViewPanel(v22r2.diagnostic.TestSetupPageViewPanel):
    NR = "NR"
    ALL_NR_CELLS = "All NR cells"

    def __init__(self, driver):
        super(TestSetupPageViewPanel, self).__init__(driver)

    def configure_rf_diagnostic_test(self, activate, cell, bts_thresholds, bands_thresholds, timeout, technology='NR'):
        if not self.elements_is_visible((By.XPATH, self._TDS_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CHECK_XPATH,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CLICK_XPATH)

        self.click_enabled_element((By.XPATH, self._TECHNOLOGY.format(technology.lower())), timeout)

        if technology == self.NR and "All" in cell:
            cell = self.ALL_NR_CELLS
        self.select_element_from_dropdown_list_by_text_and_click(cell,
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_BUTTON),
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_ITEM),
                                                                 timeout)
        self.configure_and_check_bts_thresholds(bts_thresholds, timeout)
        self._configure_bands_thresholds(bands_thresholds, timeout)

    def configure_statistics_diagnostic_test(self, activate, radio, timeout=60):
        if not self.elements_is_visible((By.XPATH, self._TDS_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CHECK_XPATH,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CLICK_XPATH)

        self.select_element_from_dropdown_list_by_text_and_click(
            radio,
            (By.XPATH, self._START_STATISTICS_TEST_FOR_RADIO_DROPDOWN_BUTTON),
            (By.XPATH, self._START_STATISTICS_TEST_FOR_CELL_DROPDOWN_ITEM),
            timeout)
